-- Step 1: Users, their Sessions (refresh tokens) and failed logins for the lockout (Card 2).
-- Ids are uuid v7, generated by the Go code.

-- +goose Up
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TYPE user_role AS ENUM ('admin', 'member');

CREATE TABLE users (
    id            uuid PRIMARY KEY,
    email         citext      NOT NULL UNIQUE,
    password_hash text        NOT NULL,
    display_name  varchar(40) NOT NULL CHECK (char_length(display_name) >= 2),
    role          user_role   NOT NULL,
    active        boolean     NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

-- One row per refresh token. Every token issued for one login shares a session_id (see Session in GLOSSARY.md).
-- A rotated token has revoked_at set and replaced_by pointing at its successor.
CREATE TABLE refresh_tokens (
    id          uuid PRIMARY KEY,
    user_id     uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    session_id  uuid        NOT NULL,
    token_hash  text        NOT NULL UNIQUE,
    expires_at  timestamptz NOT NULL,
    revoked_at  timestamptz,
    replaced_by uuid REFERENCES refresh_tokens (id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX refresh_tokens_user_id_idx ON refresh_tokens (user_id);
CREATE INDEX refresh_tokens_session_id_idx ON refresh_tokens (session_id);

-- One row per failed or refused login, for any email, including emails with no User (Card 2 rules 2 and 3).
-- Rows are never updated, so there is no updated_at.
-- No foreign key on purpose: unknown emails must lock exactly like known ones.
CREATE TABLE login_failures (
    id         uuid PRIMARY KEY,
    email      citext      NOT NULL,
    failed_at  timestamptz NOT NULL DEFAULT now(),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX login_failures_email_failed_at_idx ON login_failures (email, failed_at);

-- +goose Down
DROP TABLE login_failures;
DROP TABLE refresh_tokens;
DROP TABLE users;
DROP TYPE user_role;
